function uniqueSorted(nums) {
  return [...new Set(nums)].sort((a, b) => a - b)
}

function reverseWords(str) {
  const t = str.trim()
  if (t === '') return ''
  return t.split(/\s+/).reverse().join(' ')
}

function countCopies(n) {
  let cap = 1, size = 0, copies = 0
  for (let i = 0; i < n; i++) {
    if (size === cap) {
      copies += size
      cap *= 2
    }
    size++
  }
  return copies
}
